in, stdout, stderr = ssh.exec_command(\\\\\\\"sudo cat /config/.storage/core.entity_registry\\\\\\\")\\\\nreg_data = stdout.read().decode()\\\\nwith open('/home/ahmad/antigravity/entity_registry.json', 'w') as f:\\\\n    f.write(reg_data)\\\\n\\\\nreg = json.loads(reg_data)\\\\nentities = reg['data']['entities']\\\\n\\\\n# Group by domain\\\\ndomains = {}\\\\nfor e in entities:\\\\n    domain = e['entity_id'].split('.')[0]\\\\n    if domain not in domains:\\\\n        domains[domain] = []\\\\n    domains[domain].append({\\\\n        'id': e['entity_id'],\\\\n        'name': e.get('name') or e.get('original_name') or '',\\\\n        'platform': e.get('platform', ''),\\\\n        'disabled': e.get('disabled_by') is not None\\\\n    })\\\\n\\\\nprint(\\\\\\\"\\\\\\\\n=== Entity Summary ===\\\\\\\")\\\\nfor domain in sorted(domains.keys()):\\\\n    active = [e for e in domains[domain] if not e['disabled']]\\\\n    print(f\\\\\\\"\\\\\\\\n--- {domain} ({len(active)} active) ---\\\\\\\")\\\\n    for e in active:\\\\n        print(f\\\\\\\"  {e['id']} [{e['platform']}] {e['name']}\\\\\\\")\\\\n\\\\n# 3. Get existing dashboards\\\\nstdin, stdout, stderr = ssh.exec_command(\\\\\\\"sudo ls -la /config/.storage/lovelace*\\\\\\\")\\\\nprint(\\\\\\\"\\\\\\\\n=== Existing Dashboards ===\\\\\\\")\\\\nprint(stdout.read().decode().strip())\\\\n\\\\n# 4. Check HA version\\\\nstdin, stdout, stderr = ssh.exec_command(\\\\\\\"sudo docker exec homeassistant cat /VERSION 2\u003e/dev/null || echo 'unknown'\\\\\\\")\\\\nprint(\\\\\\\"\\\\\\\\n=== HA Version ===\\\\\\\")\\\\nprint(stdout.read().decode().strip())\\\\n\\\\nssh.close()\\\\n\\\"\",\"Description\":\"\\\"Research all available entities, dashboards, and HA version for kiosk dashboard planning\\\"\",\"Overwrite\":\"true\",\"TargetFile\":\"\\\"/home/ahmad/antigravity/ha_research.py\\\"\",\"toolAction\":\"\\\"Creating research script\\\"\",\"toolSummary\":\"\\\"Research HA entities\\\"\"}}]}"}
